@startuml

class InsuranceCompany {}

class Customer {
  + name : string
  + address : string
  + accountDetails : string
}

class Broker {
  + brokerId : int
  + name : string
}

class Policy {
  + policyType : string
  + coverageDetails : string
}

class Offer {
  + offerId : int
  + preliminaryTerms : string
  + offerDate : date
}

class Contract {
  + contractNumber : int
  + signingDate : date
  + billingFrequency : string
  + price : float
}

class ClaimCase {
  + caseId : int
  + status : string
  + description : string
}

class Estimator {
  + estimatorId : int
  + areaOfExpertise : string
}

class EstimatorReport {
  + reportId : int
  + findings : string
  + reportDate : date
}

class CompensationDecision {
  + decisionId : int
  + isApproved : boolean
  + eligibleCosts : string
}

class Payment {
  + paymentId : int
  + amount : float
  + paymentDate : date
}

InsuranceCompany "1" -- "*" Customer
Broker "1" -- "*" Customer : manages
Customer "1" -- "*" Contract
Customer "1" -- "*" Offer
Offer "1" -- "1" Contract
Contract "1" -- "1" Policy
Customer "1" -- "*" ClaimCase
ClaimCase "1" *-- "1..*" EstimatorReport
Estimator "1" -- "*" EstimatorReport
EstimatorReport "1..*" -- "1" CompensationDecision
CompensationDecision "1" -- "1" Payment
Payment "1" -- "1" Customer

@enduml

